import org.jsoup.nodes.Comment;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.ArrayList;

public class CommentTest {
    @Test
    public void constructorWithDataTest() {
        Comment comment = new Comment("data");
        assertNotNull(comment);
        assertEquals("data", comment.getData());
    }

    @Test
    public void getDataWithoutDataTest() {
        Comment comment = new Comment(null);
        assertNull(comment.getData());
    }

    @Test
    public void outerHtmlForCommentWithEmptyStringShouldBeEmpty() {
        Comment comment = new Comment("");
        String result = comment.getOuterHtml();
        assertEquals("", result);
    }

    @Test
    public void outerHtmlForCommentWithoutOpeningTagShouldStartWithSlash() {
        Comment comment = new Comment("data");
        String result = comment.getOuterHtml();
        assertTrue(result.startsWith("/"));
    }

    @Test
    public void outerHtmlForCommentWithoutClosingTagShouldEndWithSlash() {
        Comment comment = new Comment("data");
        String result = comment.getOuterHtml();
        assertTrue(result.endsWith("/"));
    }

    @Test
    public void outerHtmlForCommentWithOpeningAndClosingTagsShouldHaveCorrectFormat() {
        Comment comment = new Comment("data");
        String result = comment.getOuterHtml();
        assertTrue(result.startsWith("<") && result.endsWith(">"));
    }
}

public class Comment {
    private String data;

    public Comment(String data) {
        this.data = data;
    }

    public String getData() {
        return data;
    }

    public String getOuterHtml() {
        return "<" + data + ">";
    }
}
